Lemma up_fast : forall (k j : nat) (Q : machine_state -> Prop) rax spx gp tp t0 t1 t2 s0 s1 a0 a2 a4 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) (VQ vp : Z) (vbs : list byte),
  (7 - j = k)%nat -> (j <= 7)%nat ->
  bytes_at usegs m1 vp vbs -> bytes_at usegs m1 A_UPGRADE (litb LIT_UPGRADE) ->
  vp <= VQ -> VQ + 7 <= vp + Z.of_nat (length vbs) -> vp + Z.of_nat (length vbs) < 2^64 -> 0 < vp ->
  mem_inv usegs m1 ->
  conn_cont Q 0x3fba0 (wz 256) rax spx gp tp t2 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m1 ->
  (forall a0', conn_cont Q 0x3fbac a0' rax spx gp tp t2 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m1) ->
  evt usegs Q (MS (mkR rax spx gp tp t0 t1 t2 s0 s1 a0 (wz VQ) a2 (Z_to_bv 64 (Z.of_nat j - 7)) a4 (wz (7 - Z.of_nat j)) a6 a7
                       s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
