(* [comment removed for export] *)
Lemma ka_slow : forall (k j : nat) (Q : machine_state -> Prop) rax spx gp tp t0 t1 t2 s0 s1 a1 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) (VQ vp : Z) (vbs : list byte),
  (10 - j = k)%nat -> (j < 10)%nat ->
  bytes_at usegs m1 vp vbs -> bytes_at usegs m1 A_KEEPALIVE (litb LIT_KEEPALIVE) ->
  vp <= VQ -> VQ + 10 <= vp + Z.of_nat (length vbs) -> vp + Z.of_nat (length vbs) < 2^64 -> 0 < vp ->
  mem_inv usegs m1 ->
  conn_cont Q 0x3fba0 (wz 512) rax spx gp tp t2 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m1 ->
  (forall a0', conn_cont Q 0x3fbac a0' rax spx gp tp t2 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m1) ->
  evt usegs Q (MS (mkR rax spx gp tp t0 t1 t2 s0 s1 (wz 512) a1 (wz 10) (wz (10 - Z.of_nat j)) (wz (A_KEEPALIVE + Z.of_nat j)) (wz (VQ + Z.of_nat j))
                       a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
