(* [comment removed for export] *)
Definition conn_ctx (m m1 : mem) (sp : word) (sv : list word) (P E lo : Z) (c : pcore) (pad7 pad2 : list byte) (f1 : Z)
    (vp : Z) (vbs : list byte) (j1 j2 : list byte) (optc : list cell) (e1 e2 e3 : word) (g : bool) : Prop :=
  rw_cells usegs m1 (bv_unsigned sp + -288) [CB 40 j1]
  /\ rw_cells usegs m1 (bv_unsigned sp + -248) [C8 (wz vp); C8 (wz (Z.of_nat (length vbs)))]
  /\ rw_cells usegs m1 (bv_unsigned sp + -232) [CB 144 j2]
  /\ rw_cells usegs m1 (bv_unsigned sp + -88) optc
  /\ rw_cells usegs m1 (bv_unsigned sp + -48) (map C8 sv)
  /\ rw_cells usegs m1 P (ParserCoreCells (mkPC (pc_blim_has c) (pc_blim c) (pc_len c) (pc_len0 c) (pc_skip c) (pc_hlim c) (pc_state c) f1) pad7 pad2)
  /\ rw_cells usegs m1 E [C8 e1; C8 e2; C8 e3]
  /\ bytes_at usegs m1 vp vbs
  /\ HttpCat m1 g /\ XStatics m1
  /\ stk usegs m1 lo (bv_unsigned sp + -288)
  /\ munch (dof_W lo sp P E) m m1 /\ wmono usegs m m1 /\ mem_inv usegs m1.

Local Ltac conn_open CTX PURE sp :=
  destruct CTX as (F0 & LSV & MIDB & OPT & FRhi & PC & EC & WIN & HC & XS & ST & MU & WM & MI);
  destruct PURE as (PCOK & FLD & LO & IMG & QLO & QHI & PLO & PHI & ELO & EHI & DPE & VLEN);
  pose proof PCOK as PCOK0; destruct PCOK as (Bh & Bl & Ln & Ln0 & Sk & Hl & Stt & Ff);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  unfold dof_W, G_HTTP_CAT in *; unfold dof_sv in FRhi; cbn [map] in FRhi;
  unfold ParserCoreCells in PC; cbn [pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f] in PC;
  unfold wz in *.

