Lemma conn_ret : forall (optc : list cell) rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s2x s3x s4x s5 s6 s7
         s0v s1v s2v s3v s4v s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P E lo : Z) (c : pcore) (pad7 pad2 : list byte) (f1 vp : Z) (vbs : list byte)
    (j1 j2 : list byte) (e1 e2 e3 : word) (g : bool),
  conn_ctx m m1 sp (dof_sv s4v s3v s2v s1v s0v ra) P E lo c pad7 pad2 f1 vp vbs j1 j2 optc e1 e2 e3 g -> cells_size optc = 40%nat ->
  dof_pure sp P E lo c (pc_state c) vp vbs -> 0 <= f1 < 2^14 ->
  evt usegs (dof_post ra sp gp tp s0v s1v s2v s3v s4v s5 s6 s7 s8 s9 s10 s11 F fc P E lo c pad7 pad2 vp vbs m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -288)) gp tp t0 t1 t2 (wz E) (wz P) a0 a1 a2 a3 a4 a5 a6 a7
              s2x s3x s4x s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x3f918) fc None m1 (seg_rom usegs)).
