(* [comment removed for export] *)
Definition CONN_AT (mu : nat) : Prop :=
  forall (r : tokres) (it err : Z) rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s3x s4x s5 s6 s7
         s0v s1v s2v s3v s4v s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P E lo : Z) (c : pcore) (pad7 pad2 : list byte) (f1 vp : Z) (vbs : list byte)
    (j1 j2 pad7o : list byte) (e1 e2 e3 : word) (g : bool),
  conn_ctx m m1 sp (dof_sv s4v s3v s2v s1v s0v ra) P E lo c pad7 pad2 f1 vp vbs j1 j2
           (optit_cells_after r (bv_unsigned sp + -248) it err pad7o) e1 e2 e3 g ->
