(* [comment removed for export] *)
Lemma conn_orf : forall mu, CONN_AT mu ->
  forall (bit itc vq vl err : Z) rax ra sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s3x s4x s5 s6 s7
         s0v s1v s2v s3v s4v s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P E lo : Z) (c : pcore) (pad7 pad2 : list byte) (f1 vp : Z) (vbs : list byte)
    (j1 j2 pad7o : list byte) (e1 e2 e3 : word) (g : bool),
  conn_ctx m m1 sp (dof_sv s4v s3v s2v s1v s0v ra) P E lo c pad7 pad2 f1 vp vbs j1 j2
           (OptItCells (bv_unsigned sp + -248) itc vq vl err pad7o) e1 e2 e3 g ->
  dof_pure sp P E lo c (pc_state c) vp vbs -> 0 <= f1 < 2^14 -> 0 <= err < 2 -> 0 <= bit < 2^14 ->
  vp <= vq -> 1 <= vl -> vq + vl = itc -> itc <= vp + Z.of_nat (length vbs) -> vp + Z.of_nat (length vbs) - itc < Z.of_nat mu ->
  bv_unsigned sp mod 16 = 0 ->
  evt usegs (dof_post ra sp gp tp s0v s1v s2v s3v s4v s5 s6 s7 s8 s9 s10 s11 F fc P E lo c pad7 pad2 vp vbs m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -288)) gp tp t0 t1 t2 (wz E) (wz P) (wz bit) a1 a2 a3 a4 a5 a6 a7
              (Z_to_bv 64 (bv_unsigned sp + -248)) s3x s4x s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
