Lemma conn_all : forall n, CONN_AT n.
Proof.
  induction n as [|n IH].
  - intros r it err. intros until g. intros CTX PURE F1 ERR N1 N2 HR NM ALSP. exfalso. cbn [Z.of_nat] in NM. lia.
  - apply conn_step. exact IH.
Qed.

